414	#define MI_RETIRE_CYCLES      (16)      /* keep a retired page around for about 16 "admin cycles" before free'ing it */
415	#define MI_RETIRE_MAX_PAGES   (3)       /* keep at most N pages per size bin as retired */
416	
417	// Retire a page with no more used blocks
418	// Important to not retire too quickly though as new
419	// allocations might coming.
420	//
421	// Note: called from `mi_free` and benchmarks often
422	// trigger this due to freeing everything and then
423	// allocating again so careful when changing this.
424	void _mi_page_retire(mi_page_t* page) mi_attr_noexcept {
425	  mi_assert_internal(page != NULL);
426	  mi_assert_expensive(_mi_page_is_valid(page));
427	  mi_assert_internal(mi_page_all_free(page));
428	
429	  if (page->retire_expire!=0) return;  // already retired, just keep it retired
430	  mi_page_set_has_interior_pointers(page, false);
431	
432	  // don't retire too often..
433	  // (or we end up retiring and re-allocating most of the time)
434	  // NOTE: refine this more: we should not retire if this
435	  // is the only page left with free blocks. It is not clear
436	  // how to check this efficiently though...
437	  // for now, we don't retire if it is the only page left of this size class.
438	  mi_page_queue_t* pq = mi_page_queue_of(page);
439	  #if MI_RETIRE_CYCLES > 0
440	  const size_t bsize = mi_page_block_size(page);
441	  if mi_likely( pq->count <= MI_RETIRE_MAX_PAGES && !mi_page_queue_is_special(pq)) {  // not full or huge queue?
442	    if (pq->count==1 || bsize < MI_SMALL_SIZE_MAX) {
443	      mi_theap_t* theap = mi_page_theap(page);
444	      mi_theap_stat_counter_increase(theap, pages_retire, 1);
445	      page->retire_expire = (bsize <= MI_SMALL_MAX_OBJ_SIZE ? MI_RETIRE_CYCLES : MI_RETIRE_CYCLES/4);
446	      mi_assert_internal(pq >= theap->pages);
447	      const size_t index = pq - theap->pages;
448	      mi_assert_internal(index < MI_BIN_FULL && index < MI_BIN_HUGE);
449	      if (index < theap->page_retired_min) theap->page_retired_min = index;
450	      if (index > theap->page_retired_max) theap->page_retired_max = index;
451	      mi_assert_internal(mi_page_all_free(page));
452	      return; // don't free after all
453	    }  
454	  }
455	  #endif
456	  _mi_page_free(page, pq);
457	}
