460	static void mi_theap_collect_full_pages(mi_theap_t* theap) {
461	  // note: normally full pages get immediately abandoned and the full queue is always empty
462	  // this path is only used if abandoning is disabled due to a destroy-able theap or options
463	  // set by the user.
464	  mi_page_queue_t* pq = &theap->pages[MI_BIN_FULL];
465	  for (mi_page_t* page = pq->first; page != NULL; ) {
466	    mi_page_t* next = page->next;         // get next in case we free the page
467	    _mi_page_free_collect(page, false);   // register concurrent free's
468	    // no longer full?
469	    if (!mi_page_is_full(page)) {
470	      if (mi_page_all_free(page)) {
471	        _mi_page_free(page, pq);
472	      }
473	      else {
474	        _mi_page_unfull(page);
475	      }
476	    }
477	    page = next;
478	  }
479	}
480	
481	static void mi_page_try_retire(mi_page_queue_t* pq, mi_page_t* page, size_t bin, bool force, size_t* min, size_t* max) {    
482	  mi_assert_internal(page!=NULL && page->retire_expire!=0);
483	  if (mi_page_all_free(page)) {
484	    page->retire_expire--;
485	    if (page->retire_expire == 0 || force) {
486	      _mi_page_free(page, pq);
487	    }
488	    else {
489	      // keep retired, update min/max
490	      if (bin < *min) *min = bin;
491	      if (bin > *max) *max = bin;
492	    }
493	  }
494	  else {
495	    page->retire_expire = 0;
496	  }  
497	}
498	
499	// free retired pages: we don't need to look at the entire queues
500	// since we only retire pages that are at the head position in a queue.
501	void _mi_theap_collect_retired(mi_theap_t* theap, bool force) {
502	  size_t min = MI_BIN_FULL;
503	  size_t max = 0;
504	  for(size_t bin = theap->page_retired_min; bin <= theap->page_retired_max; bin++) {
505	    mi_page_queue_t* pq  = &theap->pages[bin];
506	    mi_page_t* page      = pq->first;
507	    for (int i = 0; i<MI_RETIRE_MAX_PAGES && page!=NULL && page->retire_expire!=0; i++) {
508	      mi_page_t* next = page->next;
509	      mi_page_try_retire(pq,page,bin,force,&min,&max);
510	      page = next;
511	    }
512	  }
513	  theap->page_retired_min = min;
514	  theap->page_retired_max = max;
515	  if (!theap->allow_page_abandon) {
516	    mi_theap_collect_full_pages(theap);
517	  }
518	}
