523	/* -----------------------------------------------------------
524	  Initialize the initial free list in a page.
525	  In secure mode we initialize a randomized list by
526	  alternating between slices.
527	----------------------------------------------------------- */
528	
529	#define MI_MAX_SLICE_SHIFT  (6)   // at most 64 slices
530	#define MI_MAX_SLICES       (1UL << MI_MAX_SLICE_SHIFT)
531	#define MI_MIN_SLICES       (2)
532	
533	static void mi_page_free_list_extend_secure(mi_theap_t* const theap, mi_page_t* const page, const size_t bsize, const size_t extend) {
534	  #if (MI_SECURE < 2)
535	  mi_assert_internal(page->free == NULL);
536	  mi_assert_internal(page->local_free == NULL);
537	  #endif
538	  mi_assert_internal(page->capacity + extend <= page->reserved);
539	  mi_assert_internal(bsize == mi_page_block_size(page));
540	  void* const page_area = mi_page_start(page);
541	
542	  // initialize a randomized free list
543	  // set up `slice_count` slices to alternate between
544	  size_t shift = MI_MAX_SLICE_SHIFT;
545	  while ((extend >> shift) == 0) {
546	    shift--;
547	  }
548	  const size_t slice_count = (size_t)1U << shift;
549	  const size_t slice_extend = extend / slice_count;
550	  mi_assert_internal(slice_extend >= 1);
551	  mi_block_t* blocks[MI_MAX_SLICES];   // current start of the slice
552	  size_t      counts[MI_MAX_SLICES];   // available objects in the slice
553	  for (size_t i = 0; i < slice_count; i++) {
554	    blocks[i] = mi_page_block_at(page, page_area, bsize, page->capacity + i*slice_extend);
555	    counts[i] = slice_extend;
556	  }
557	  counts[slice_count-1] += (extend % slice_count);  // final slice holds the modulus too (todo: distribute evenly?)
558	
559	  // and initialize the free list by randomly threading through them
560	  // set up first element
561	  const uintptr_t r = _mi_theap_random_next(theap);
562	  size_t current = r % slice_count;
563	  counts[current]--;
564	  mi_block_t* const free_start = blocks[current];
565	  // and iterate through the rest; use `random_shuffle` for performance
566	  uintptr_t rnd = _mi_random_shuffle(r|1); // ensure not 0
567	  for (size_t i = 1; i < extend; i++) {
568	    // call random_shuffle only every INTPTR_SIZE rounds
569	    const size_t round = i%MI_INTPTR_SIZE;
570	    if (round == 0) rnd = _mi_random_shuffle(rnd);
571	    // select a random next slice index
572	    size_t next = ((rnd >> 8*round) & (slice_count-1));
573	    while (counts[next]==0) {                            // ensure it still has space
574	      next++;
575	      if (next==slice_count) next = 0;
576	    }
577	    // and link the current block to it
578	    counts[next]--;
579	    mi_block_t* const block = blocks[current];
580	    blocks[current] = (mi_block_t*)((uint8_t*)block + bsize);  // bump to the following block
581	    mi_block_set_next(page, block, blocks[next]);   // and set next; note: we may have `current == next`
582	    current = next;
583	  }
584	  // prepend to the free list (usually NULL)
585	  mi_block_set_next(page, blocks[current], page->free);  // end of the list
586	  page->free = free_start;
587	}
588	
589	static mi_decl_noinline void mi_page_free_list_extend( mi_page_t* const page, const size_t bsize, const size_t extend)
590	{
591	  #if (MI_SECURE < 2)
592	  mi_assert_internal(page->free == NULL);
593	  mi_assert_internal(page->local_free == NULL);
594	  #endif
595	  mi_assert_internal(page->capacity + extend <= page->reserved);
596	  mi_assert_internal(bsize == mi_page_block_size(page));
597	  void* const page_area = mi_page_start(page);
598	
599	  mi_block_t* const start = mi_page_block_at(page, page_area, bsize, page->capacity);
600	
601	  // initialize a sequential free list
602	  mi_block_t* const last = mi_page_block_at(page, page_area, bsize, page->capacity + extend - 1);
603	  mi_block_t* block = start;
604	  while(block <= last) {
605	    mi_block_t* next = (mi_block_t*)((uint8_t*)block + bsize);
606	    mi_block_set_next(page,block,next);
607	    block = next;
608	  }
609	  // prepend to free list (usually `NULL`)
610	  mi_block_set_next(page, last, page->free);
611	  page->free = start;
612	}
613	
614	/* -----------------------------------------------------------
615	  Page initialize and extend the capacity
616	----------------------------------------------------------- */
617	
618	#define MI_MAX_EXTEND_SIZE    (8*1024)      // heuristic, one or two OS pages seems to work well.
619	#if (MI_SECURE>=2)
620	#define MI_MIN_EXTEND         (8*MI_SECURE) // extend at least by this many
621	#else
622	#define MI_MIN_EXTEND         (1)
623	#endif
624	
625	// Extend the capacity (up to reserved) by initializing a free list
626	// We do at most `MI_MAX_EXTEND` to avoid touching too much memory
627	// Note: we also experimented with "bump" allocation on the first
628	// allocations but this did not speed up any benchmark (due to an
629	// extra test in malloc? or cache effects?)
630	static bool mi_page_extend_free(mi_theap_t* theap, mi_page_t* page) {
631	  mi_assert_expensive(mi_page_is_valid_init(page));
632	  #if (MI_SECURE < 2)
633	  mi_assert(page->free == NULL);
634	  mi_assert(page->local_free == NULL);
635	  if (page->free != NULL) return true;
636	  #endif
637	  if (page->capacity >= page->reserved) return true;
638	
639	  size_t page_size;
640	  //uint8_t* page_start =
641	  mi_page_area(page, &page_size);
642	  #if MI_STAT>0
643	  mi_theap_stat_counter_increase(theap, pages_extended, 1);
644	  #endif
645	
646	  // calculate the extend count
647	  const size_t bsize = mi_page_block_size(page);
648	  size_t extend = (size_t)page->reserved - page->capacity;
649	  mi_assert_internal(extend > 0);
650	
651	  size_t max_extend = (bsize >= MI_MAX_EXTEND_SIZE ? MI_MIN_EXTEND : MI_MAX_EXTEND_SIZE/bsize);
652	  if (max_extend < MI_MIN_EXTEND) { max_extend = MI_MIN_EXTEND; }
653	  mi_assert_internal(max_extend > 0);
654	
655	  if (extend > max_extend) {
656	    // ensure we don't touch memory beyond the page to reduce page commit.
657	    // the `lean` benchmark tests this. Going from 1 to 8 increases rss by 50%.
658	    extend = max_extend;
659	  }
660	
661	  mi_assert_internal(extend > 0 && extend + page->capacity <= page->reserved);
662	  mi_assert_internal(extend < (1UL<<16));
663	
664	  // commit on demand?
665	  const size_t slice_committed = mi_page_slice_committed(page);
666	  if (slice_committed > 0) {
667	    // reduce extend if it commits more than an arena slice
668	    if ((extend * bsize) > MI_ARENA_SLICE_SIZE) {
669	      extend = _mi_divide_up(MI_ARENA_SLICE_SIZE, bsize);
670	    }
671	    // commit required size
672	    const size_t needed_size = (page->capacity + extend)*bsize;
673	    mi_assert_internal(needed_size <= page_size);
674	    size_t needed_commit = _mi_align_up( mi_page_slice_offset_of(page, needed_size), mi_page_min_commit_size());
675	    #if MI_SECURE>=5
676	    // the previous alignup could extend the commit into the guard page; re-adjust if needed
677	    const size_t page_size_commit = _mi_align_up( mi_page_slice_offset_of(page, page_size), _mi_os_page_size() );    
678	    if (needed_commit > page_size_commit) { 
679	      needed_commit = page_size_commit;
680	    }
681	    #endif
682	    if (needed_commit > slice_committed) {
683	      mi_assert_internal(((needed_commit - slice_committed) % _mi_os_page_size()) == 0);
684	      if (!_mi_os_commit(_mi_theap_subproc(theap), mi_page_slice_start(page) + slice_committed, needed_commit - slice_committed, NULL)) {
685	        return false;
686	      }
687	      mi_assert_internal(needed_commit <= UINT16_MAX * _mi_os_page_size());
688	      page->slice_pcommitted = (uint16_t)(needed_commit / _mi_os_page_size());
689	    }
690	  }
691	
692	  // and append the extend the free list
693	  if (extend < MI_MIN_SLICES || MI_SECURE<2) { //!mi_option_is_enabled(mi_option_secure)) {
694	    mi_page_free_list_extend(page, bsize, extend );
695	  }
696	  else {
697	    mi_page_free_list_extend_secure(theap, page, bsize, extend);
698	  }
699	  // enable the new free list
700	  page->capacity += (uint16_t)extend;
701	  #if MI_STAT>0
702	  mi_theap_stat_increase(theap, page_committed, extend * bsize);
703	  #endif
704	  mi_assert_expensive(mi_page_is_valid_init(page));
705	  return true;
706	}
707	
708	// Initialize a fresh page (that is already partially initialized)
709	mi_decl_nodiscard bool _mi_page_init(mi_theap_t* theap, mi_page_t* page) {
710	  mi_assert(page != NULL);
711	  mi_assert(theap!=NULL);
712	  // page->heap = (_mi_is_heap_main(_mi_theap_heap(theap)) ? NULL : _mi_theap_heap(theap)); // faster for `mi_page_associated_theap`
713	  // mi_page_set_theap(page, theap);
714	
715	  size_t page_size;
716	  uint8_t* page_start = mi_page_area(page, &page_size); MI_UNUSED(page_start);
717	  mi_track_mem_noaccess(page_start,page_size);
718	  mi_assert_internal(page_size / mi_page_block_size(page) < (1L<<16));
719	  mi_assert_internal(page->reserved > 0);
720	  #if (MI_PADDING || MI_ENCODE_FREELIST)
721	  page->keys[0] = _mi_theap_random_next(theap);
722	  #if MI_PAGE_KEY_COUNT==2
723	  page->keys[1] = _mi_theap_random_next(theap);
724	  #endif
725	  #endif
726	  #if MI_DEBUG>2
727	  if (page->memid.initially_zero) {
728	    mi_track_mem_defined(mi_page_start(page), mi_page_committed(page));
729	    mi_assert_expensive(mi_mem_is_zero(page_start, mi_page_committed(page)));
730	  }
731	  #endif
732	
733	  mi_assert_internal(page->heap != NULL);
734	  mi_assert_internal(page->heap == _mi_theap_heap(theap));
735	  mi_assert_internal(page->theap!=NULL);
736	  mi_assert_internal(page->theap == mi_page_theap(page));
737	  mi_assert_internal(page->capacity == 0);
738	  mi_assert_internal(page->free == NULL);
739	  mi_assert_internal(page->used == 0);
740	  mi_assert_internal(mi_page_is_owned(page));
741	  mi_assert_internal(page->xthread_free == 1);
742	  mi_assert_internal(page->next == NULL);
743	  mi_assert_internal(page->prev == NULL);
744	  mi_assert_internal(page->retire_expire == 0);
745	  mi_assert_internal(!mi_page_has_interior_pointers(page));
746	  #if (MI_PADDING || MI_ENCODE_FREELIST)
747	  mi_assert_internal(page->keys[0] != 0);
748	  #if MI_PAGE_KEY_COUNT==2
749	  mi_assert_internal(page->keys[1] != 0);
750	  #endif
751	  #endif
752	  mi_assert_expensive(mi_page_is_valid_init(page));
753	
754	  // initialize an initial free list
755	  if (!mi_page_extend_free(theap,page)) return false;
756	  mi_assert(mi_page_immediate_available(page));
757	  return true;
758	}
759	
760	
761	/* -----------------------------------------------------------
762	  Find pages with free blocks
763	-------------------------------------------------------------*/
764	
765	// Find a page with free blocks of `page->block_size`.
766	static mi_decl_noinline mi_page_t* mi_page_queue_find_free_ex(mi_theap_t* theap, mi_page_queue_t* pq, bool first_try)
767	{
768	  // search through the pages in "next fit" order
769	  size_t count = 0;
770	  long candidate_limit = 0;          // we reset this on the first candidate to limit the search
771	  long page_full_retain = (pq->block_size > MI_SMALL_MAX_OBJ_SIZE ? 0 : theap->page_full_retain); // only retain small pages
772	  mi_page_t* page_candidate = NULL;  // a page with free space
773	  mi_page_t* page = pq->first;
774	
775	  while (page != NULL)
776	  {
777	    mi_page_t* next = page->next; // remember next (as this page can move to another queue)
778	    count++;
779	    candidate_limit--;
780	
781	    // search up to N pages for a best candidate
782	
783	    // is the local free list non-empty?
784	    bool immediate_available = mi_page_immediate_available(page);
785	    if (!immediate_available) {
786	      // collect freed blocks by us and other threads to we get a proper use count
787	      _mi_page_free_collect(page, false);
788	      immediate_available = mi_page_immediate_available(page);
789	    }
790	
791	    // if the page is completely full, move it to the `mi_pages_full`
792	    // queue so we don't visit long-lived pages too often.
793	    if (!immediate_available && !mi_page_is_expandable(page)) {
794	      page_full_retain--;
795	      if (page_full_retain < 0) {
796	        mi_assert_internal(!mi_page_is_in_full(page) && !mi_page_immediate_available(page));
797	        mi_page_to_full(page, pq);
798	      }
799	    }
800	    else {
801	      // the page has free space, make it a candidate
802	      // we prefer non-expandable pages with high usage as candidates (to reduce commit, and increase chances of free-ing up pages)
803	      if (page_candidate == NULL) {
804	        page_candidate = page;
805	        candidate_limit = _mi_option_get_fast(mi_option_page_max_candidates);
806	      }
807	      else if (mi_page_all_free(page_candidate)) {
808	        _mi_page_free(page_candidate, pq);
809	        page_candidate = page;
810	      }
811	      // prefer to reuse fuller pages (in the hope the less used page gets freed)
812	      else if (page->used >= page_candidate->used && !mi_page_is_mostly_used(page)) { // && !mi_page_is_expandable(page)) {
813	        page_candidate = page;
814	      }
815	      // if we find a non-expandable candidate, or searched for N pages, return with the best candidate
816	      if (immediate_available || candidate_limit <= 0) {
817	        mi_assert_internal(page_candidate!=NULL);
818	        break;
819	      }
820	    }
821	
822	  #if 0
823	    // first-fit algorithm without candidates
824	    // If the page contains free blocks, we are done
825	    if (mi_page_immediate_available(page) || mi_page_is_expandable(page)) {
826	      break;  // pick this one
827	    }
828	
829	    // If the page is completely full, move it to the `mi_pages_full`
830	    // queue so we don't visit long-lived pages too often.
831	    mi_assert_internal(!mi_page_is_in_full(page) && !mi_page_immediate_available(page));
832	    mi_page_to_full(page, pq);
833	  #endif
834	
835	    page = next;
836	  } // for each page
837	
838	  mi_theap_stat_counter_increase(theap, page_searches, count);
839	  mi_theap_stat_counter_increase(theap, page_searches_count, 1);
840	
841	  // set the page to the best candidate
842	  if (page_candidate != NULL) {
843	    page = page_candidate;
844	  }
845	  if (page != NULL) {
846	    if (!mi_page_immediate_available(page)) {
847	      mi_assert_internal(mi_page_is_expandable(page));
848	      if (!mi_page_extend_free(theap, page)) {
849	        page = NULL; // failed to extend
850	      }
851	    }
852	    mi_assert_internal(page == NULL || mi_page_immediate_available(page));
853	  }
854	
855	  if (page == NULL) {
856	    _mi_theap_collect_retired(theap, false); // perhaps make a page available
857	    page = mi_page_fresh(theap, pq);         
858	    mi_assert_internal(page == NULL || mi_page_immediate_available(page));
859	    if (page == NULL && first_try) {
860	      // out-of-memory _or_ an abandoned page with free blocks was reclaimed, try once again
861	      page = mi_page_queue_find_free_ex(theap, pq, false);
862	      mi_assert_internal(page == NULL || mi_page_immediate_available(page));
863	    }
864	  }
865	  else {
866	    mi_assert_internal(page == NULL || mi_page_immediate_available(page));
867	    // move the page to the front of the queue
868	    mi_page_queue_move_to_front(theap, pq, page);
869	    page->retire_expire = 0;
870	    // _mi_theap_collect_retired(theap, false); // update retire counts; note: increases rss on MemoryLoad bench so don't do this
871	  }
872	  mi_assert_internal(page == NULL || mi_page_immediate_available(page));
873	
874	
875	  return page;
876	}
877	
878	// Look for a page with free blocks of `size` but don't try to search or allocate
879	static inline mi_page_t* mi_page_queue_lookup_free_first(mi_theap_t* theap, mi_page_queue_t* pq) {
880	  mi_assert_internal(!mi_page_queue_is_huge(pq));
881	  mi_page_t* page = pq->first;
882	  if mi_likely(page!=NULL && mi_page_free_quick_collect(page)) {
883	    // fast path
884	    #if (MI_SECURE>=2) // in secure mode, we extend half the time to increase randomness
885	    if (page->capacity < page->reserved && ((_mi_theap_random_next(theap) & 1) == 1)) {
886	      (void)mi_page_extend_free(theap, page);  // ok if this fails
887	      mi_assert_internal(mi_page_immediate_available(page));
888	    }
889	    #else
890	    MI_UNUSED(theap);
891	    #endif
892	    page->retire_expire = 0;
893	    mi_assert_internal(mi_page_immediate_available(page));
894	    mi_assert_internal(_mi_is_aligned(mi_page_slice_start(page), MI_PAGE_ALIGN));
895	    mi_assert_internal(_mi_ptr_page(mi_page_start(page))==page);
896	    return page;
897	  }
898	  else {
899	    return NULL;
900	  }
901	}
902	
903	// Find a page with free blocks of `size`.
904	static inline mi_page_t* mi_page_queue_find_free(mi_theap_t* theap, mi_page_queue_t* pq) {
905	  // mi_page_queue_t* pq = mi_page_queue(theap, size);
906	  mi_assert_internal(!mi_page_queue_is_huge(pq));
907	
908	  // check the first page: we even do this with candidate search or otherwise we re-search every time
909	  mi_page_t* page = mi_page_queue_lookup_free_first(theap,pq);
910	  if (page==NULL) {
911	    page = mi_page_queue_find_free_ex(theap, pq, true);
912	    if (page==NULL) return NULL;
913	  }  
914	  mi_assert_internal(mi_page_immediate_available(page));
915	  mi_assert_internal(_mi_is_aligned(mi_page_slice_start(page), MI_PAGE_ALIGN));
916	  mi_assert_internal(_mi_ptr_page(mi_page_start(page))==page);
917	  return page;
918	}
919	
920	// Huge pages contain just one block, and the segment contains just that page.
921	// Huge pages are also use if the requested alignment is very large (> MI_BLOCK_ALIGNMENT_MAX)
922	// so their size is not always `> MI_LARGE_OBJ_SIZE_MAX`.
923	static mi_page_t* mi_huge_page_alloc(mi_theap_t* theap, size_t size, size_t page_alignment, mi_page_queue_t* pq) {
924	  const size_t block_size = _mi_os_good_alloc_size(size);
925	  // mi_assert_internal(mi_bin(block_size) == MI_BIN_HUGE || page_alignment > 0);
926	  #if MI_HUGE_PAGE_ABANDON
927	  #error todo.
928	  #else
929	  // mi_page_queue_t* pq = mi_page_queue(theap, MI_LARGE_MAX_OBJ_SIZE+1);  // always in the huge queue regardless of the block size
930	  mi_assert_internal(mi_page_queue_is_huge(pq));
931	  #endif
932	  mi_page_t* page = mi_page_fresh_alloc(theap, pq, block_size, page_alignment);
933	  if (page != NULL) {
934	    mi_assert_internal(mi_page_block_size(page) >= size);
935	    mi_assert_internal(mi_page_immediate_available(page));
936	    mi_assert_internal(mi_page_is_huge(page));
937	    mi_assert_internal(mi_page_is_singleton(page));
938	    #if MI_HUGE_PAGE_ABANDON
939	    mi_assert_internal(mi_page_is_abandoned(page));
940	    mi_page_set_theap(page, NULL);
941	    #endif
942	    mi_theap_stat_increase(theap, malloc_huge, mi_page_block_size(page));
943	    mi_theap_stat_counter_increase(theap, malloc_huge_count, 1);
944	  }
945	  return page;
946	}
947	
948	// Allocate a page
949	// Note: in debug mode the size includes MI_PADDING_SIZE and might have overflowed.
950	static mi_page_t* mi_find_page(mi_theap_t* theap, size_t size, size_t huge_alignment) mi_attr_noexcept {
951	  const size_t req_size = size - MI_PADDING_SIZE;  // correct for padding_size in case of an overflow on `size`
952	  if mi_unlikely(req_size > MI_MAX_ALLOC_SIZE) {
953	    _mi_error_message(EOVERFLOW, "allocation request is too large (%zu bytes)\n", req_size);
954	    return NULL;
955	  }
956	  mi_page_queue_t* pq = mi_page_queue(theap, (huge_alignment > 0 ? MI_LARGE_MAX_OBJ_SIZE+1 : size));
957	  mi_page_t* page;
958	  // huge allocation?
959	  if mi_unlikely(mi_page_queue_is_huge(pq) || req_size > MI_MAX_ALLOC_SIZE) {
960	    page = mi_huge_page_alloc(theap,size,huge_alignment,pq);
961	  }
962	  else {
963	    // otherwise find a page with free blocks in our size segregated queues
964	    #if MI_PADDING
965	    mi_assert_internal(size >= MI_PADDING_SIZE);
966	    #endif
967	    page = mi_page_queue_find_free(theap,pq);
968	  }
969	  if (page==NULL) return NULL;
970	  mi_assert_internal(mi_page_block_size(page) >= size);
971	  mi_assert_internal(mi_page_immediate_available(page));
972	  mi_assert_internal(_mi_is_aligned(mi_page_slice_start(page), MI_PAGE_ALIGN));
973	  mi_assert_internal(_mi_ptr_page(mi_page_start(page))==page);
974	  return page;
975	}
976	
977	
978	
979	/* -----------------------------------------------------------
980	  Users can register a deferred free function called
981	  when the `free` list is empty. Since the `local_free`
982	  is separate this is deterministically called after
983	  a certain number of allocations.
984	----------------------------------------------------------- */
985	
986	// The program should only install a single deferred free handler before doing allocation.
987	static _Atomic(void*) deferred_free; // is `mi_deferred_free_fun*` (but some platforms don't support atomic function pointers)
988	static _Atomic(void*) deferred_arg;   
989	
990	void _mi_deferred_free(mi_theap_t* theap, bool force) {
991	  theap->heartbeat++;
992	  mi_deferred_free_fun* const fun = (mi_deferred_free_fun*)mi_atomic_load_ptr_acquire(void,&deferred_free);
993	  if (fun != NULL && !theap->tld->recurse) {
994	    theap->tld->recurse = true;
995	    void* const arg = mi_atomic_load_ptr_acquire(void,&deferred_arg);  
996	    fun(force, theap->heartbeat, arg);
997	    theap->tld->recurse = false;
998	  }
999	}
1000	
1001	void mi_register_deferred_free(mi_deferred_free_fun* fn, void* arg) mi_attr_noexcept {
1002	  mi_atomic_store_ptr_release(void,&deferred_arg, arg);
1003	  mi_atomic_store_ptr_release(void,&deferred_free, (void*)fn);  
1004	}
1005	
1006	
1007	/* -----------------------------------------------------------
1008	  Admin
1009	----------------------------------------------------------- */
1010	
1011	static mi_theap_t* mi_malloc_generic_admin(mi_theap_t* theap) 
1012	{
1013	  if mi_unlikely(!mi_theap_is_initialized(theap)) {
1014	    if (theap==&_mi_theap_empty_wrong) {
1015	      // we were unable to allocate a theap for a first-class heap
1016	      return NULL;
1017	    }
1018	    // otherwise we initialize the thread and its default theap
1019	    theap = _mi_thread_init();
1020	    if mi_unlikely(!mi_theap_is_initialized(theap)) { return NULL; }    
1021	  }
1022	  mi_assert_internal(mi_theap_is_initialized(theap));
1023	
1024	  // do administrative tasks every N generic mallocs
1025	  if mi_unlikely(theap->generic_count >= 1000) {
1026	    theap->generic_collect_count += theap->generic_count;
1027	    theap->generic_count = 0;
1028	    
1029	    // do a full theap collect every once in a while (10000 by default)
1030	    const long generic_collect = mi_option_get_clamp(mi_option_generic_collect, 1, 1000000L);
1031	    if (theap->generic_collect_count >= generic_collect) {
1032	      theap->generic_collect_count = 0;
1033	      mi_theap_collect(theap, false /* force? */);
1034	    }
1035	    else {
1036	      // otherwise we do a mini-collect
1037	      _mi_deferred_free(theap, false);         // call potential deferred free routines      
1038	      _mi_theap_collect_retired(theap, false); // free retired pages      
1039	    }
1040	  }
1041	  return theap;
1042	}
1043	
1044	/* -----------------------------------------------------------
1045	  Generic allocation
1046	----------------------------------------------------------- */
1047	
1048	static mi_decl_noinline void* mi_malloc_generic_fallback(mi_theap_t* theap, size_t size, bool zero, size_t huge_alignment, mi_page_t** ppage) 
1049	{  
1050	  // initialize if necessary
1051	  theap = mi_malloc_generic_admin(theap);
1052	  if (theap==NULL) return NULL;
1053	  
1054	  // find (or allocate) a page of the right size
1055	  mi_page_t* page = mi_find_page(theap, size, huge_alignment);
1056	  if mi_unlikely(page == NULL) { // first time out of memory, try to collect and retry the allocation once more
1057	    mi_theap_collect(theap, true /* force? */);
1058	    page = mi_find_page(theap, size, huge_alignment);
1059	  }
1060	
1061	  if mi_unlikely(page == NULL) { // out of memory
1062	    const size_t req_size = size - MI_PADDING_SIZE;  // correct for padding_size in case of an overflow on `size`
1063	    _mi_error_message(ENOMEM, "unable to allocate memory (%zu bytes)\n", req_size);
1064	    return NULL;
1065	  }
1066	
1067	  mi_assert_internal(mi_page_immediate_available(page));
1068	  mi_assert_internal(mi_page_block_size(page) >= size);
1069	  mi_assert_internal(_mi_is_aligned(mi_page_slice_start(page), MI_PAGE_ALIGN));
1070	  mi_assert_internal(_mi_ptr_page(mi_page_start(page))==page);
1071	
1072	  // and try again, this time succeeding! (i.e. this should never recurse through _mi_page_malloc)
1073	  if (ppage!=NULL) { *ppage = page; }
1074	  void* const p = _mi_page_malloc_zero(theap,page,size,zero);
1075	  mi_assert_internal(p != NULL);
1076	
1077	  // move full pages to the full queue
1078	  if (mi_page_block_size(page) > MI_SMALL_MAX_OBJ_SIZE && mi_page_is_full(page)) {
1079	    mi_page_to_full(page, mi_page_queue_of(page));
1080	  }
1081	  return p;
1082	}
1083	
1084	
1085	// Generic allocation routine if the fast path (`alloc.c:mi_page_malloc`) does not succeed.
1086	// Note: in debug mode the size includes MI_PADDING_SIZE and might have overflowed.
1087	// The `huge_alignment` is normally 0 but is set to a multiple of MI_SLICE_SIZE for
1088	// very large requested alignments in which case we use a huge singleton page.
1089	// Note: we put `bool zero, size_t huge_alignment` into one parameter (with zero in the low bit)
1090	// to use 4 parameters which compiles better on msvc for the malloc fast path.
1091	void* _mi_malloc_generic(mi_theap_t* theap, size_t size, size_t zero_huge_alignment, mi_page_t** ppage) mi_attr_noexcept
1092	{
1093	  #if !MI_THEAP_INITASNULL
1094	  mi_assert_internal(theap != NULL);
1095	  #endif
1096	  const bool zero = ((zero_huge_alignment & 1) != 0);
1097	  const size_t huge_alignment = (zero_huge_alignment & ~1);
1098	  mi_page_t* page = NULL;
1099	
1100	  // fast path objects that fit in a small page
1101	  if mi_likely(mi_theap_is_initialized(theap) && ++theap->generic_count < 1000 && huge_alignment==0) {
1102	    const size_t req_size = size - MI_PADDING_SIZE;  // correct for padding_size in case of an overflow on `size`
1103	    if (req_size < MI_SMALL_MAX_OBJ_SIZE) {
1104	      mi_page_queue_t* pq = mi_page_queue(theap, size);
1105	      mi_assert_internal(pq!=NULL && !mi_page_queue_is_huge(pq));
1106	      page = mi_page_queue_find_free(theap,pq);
1107	      // mi_assert_internal(mi_page_block_size(page) <= MI_SMALL_MAX_OBJ_SIZE);
1108	      if (page!=NULL) {        
1109	        if (ppage!=NULL) { *ppage = page; }
1110	        mi_assert_internal(mi_page_immediate_available(page));
1111	        return _mi_page_malloc_zero(theap,page,size,zero);
1112	      }
1113	    }
1114	  }
1115	  // otherwise fallback
1116	  return mi_malloc_generic_fallback(theap,size,zero, huge_alignment,ppage);
1117	}
